ops.after:
const username=document.getElementById('bpAccountUsername').value.trim().normalize('NFKC');
const pw=document.getElementById('bpAccountPassword').value;
if(!/^[\p{L}\p{N}_]{2,20}$/u.test(username)){accountMessage('ユーザー名は2～20文字。日本語・英数字・_が使えるよ');return;}
if(pw.length<8||pw.length>128){accountMessage('パスワードは8～128文字で入力してね');return;}
accountMessage(register?'🔐 ユーザー名でアカウント作成中…':'🔓 ユーザー名を確認中…');
const registerButton=document.getElementById('bpAccountRegister'),loginButton=document.getElementById('bpAccountLogin');
registerButton.disabled=true;loginButton.disabled=true;
try{
 const d=await accountApi(register?'register':'login',{body:{username,password:pw}});
 if(!d.session?.accessToken)throw Error('認証に失敗したよ。もう一度試してね');
 document.getElementById('bpAccountPassword').value='';
 accountSaveSession(d.session);
 await accountLoadProfile();
 accountMessage('✅ '+(register?'メールなしでアカウント作成成功！':'ユーザー名でログイン成功！')+' ☁️ 続きを保存するなら「クラウドへ保存」を押してね');
}catch(e){accountMessage('⚠️ '+e.message);}
finally{registerButton.disabled=false;loginButton.disabled=false;}

